-- STORY-189 AC1 / owner decisions 88(a) and 91 — the business category taxonomy: 180 categories under 19 parent groups, as versioned GLOBAL data.
-- The list is the owner-approved plans-7day/categories-draft.md; rows change only by a later migration or versioned seed, never by application code.
--
--   slug              the benchmark join key (`projects.category_slug`, `platform_metrics.category_slug`). Permanent once seeded, and it does
--                     not name its group, so a category can move between groups without changing the join key.
--   name              display name.
--   parent_slug/name  the group the category sits under. A group is a parent only: it has no row of its own, so it is not selectable and is
--                     not one of the 180. `nonprofit_charities` is the one category with no parent. Both columns are set or both are NULL.
--   description       one line, written to be the text that is EMBEDDED and compared with a site's own text (decision 88(b)).
--   taxonomy_version  1 for this seed.
--
-- GLOBAL: no workspace_id, no row-level security, so GLOBAL_TABLES declares it (R2). READ-ONLY to every runtime role (decision 91): the grants
-- below are SELECT and nothing else, because a taxonomy a request handler could write would not be versioned data.
CREATE TABLE business_categories (
  slug             text        PRIMARY KEY CHECK (slug ~ '^[a-z0-9_]+$'),
  name             text        NOT NULL CHECK (name <> ''),
  parent_slug      text        CHECK (parent_slug IS NULL OR (parent_slug ~ '^[a-z0-9_]+$' AND parent_slug <> slug)),
  parent_name      text        CHECK (parent_name IS NULL OR parent_name <> ''),
  description      text        NOT NULL CHECK (description <> ''),
  taxonomy_version integer     NOT NULL DEFAULT 1 CHECK (taxonomy_version >= 1),
  created_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_business_categories_parent_pair CHECK ((parent_slug IS NULL) = (parent_name IS NULL))
);

COMMENT ON TABLE business_categories IS
  'STORY-189 — the 180-category business taxonomy (version 1). GLOBAL, read-only to runtime roles. projects.category_slug references it.';


-- Runs after ALTER DEFAULT PRIVILEGES (0005), which would otherwise have granted the two write-capable roles full DML.
REVOKE ALL ON business_categories FROM nominara_app, nominara_worker, nominara_report, nominara_portal;
GRANT SELECT ON business_categories TO nominara_app, nominara_worker, nominara_report, nominara_portal;
