INSERT INTO business_categories (slug, name, parent_slug, parent_name, description) VALUES
  ('crm', 'CRM', 'software_sales_marketing', 'Sales and marketing software', 'Software where sales teams store contacts, accounts and deals and manage a pipeline; the system of record, while `sales_engagement` runs the outreach itself.'),
  ('sales_engagement', 'Sales Engagement', 'software_sales_marketing', 'Sales and marketing software', 'Tools that run seller outreach through cadences of calls, one-to-one emails and follow-up tasks; used by individual sales reps, while `marketing_automation` sends campaigns to audiences.'),
  ('b2b_contact_data', 'B2B Contact Data', 'software_sales_marketing', 'Sales and marketing software', 'Databases of company and decision-maker details, such as verified work emails, phone numbers and firmographics, sold to prospecting teams as data rather than as a sales workflow.'),
  ('marketing_automation', 'Marketing Automation', 'software_sales_marketing', 'Sales and marketing software', 'Platforms that nurture leads through multi-channel campaigns, scoring and behaviour-triggered journeys across email, web and ads; broader than a newsletter tool such as `email_marketing_tools`.'),
  ('email_marketing_tools', 'Email Marketing Tools', 'software_sales_marketing', 'Sales and marketing software', 'Newsletter and bulk email services for building subscriber lists, designing broadcasts and tracking opens, used mainly by small businesses, online stores and writers.'),
  ('social_media_tools', 'Social Media Tools', 'software_sales_marketing', 'Sales and marketing software', 'Software for scheduling posts, managing social inboxes and reporting on brand accounts across social networks; the business''s own accounts, while `creator_affiliate_programs` manages outside partners.'),
  ('seo_tools', 'SEO Tools', 'software_sales_marketing', 'Sales and marketing software', 'Software for keyword research, backlink analysis, site audits and technical SEO, measuring presence in classic search results pages; services delivered by people belong in `seo_agencies`.'),
  ('ai_visibility_tools', 'AI Visibility Tools', 'software_sales_marketing', 'Sales and marketing software', 'Platforms that measure how AI assistants and answer engines mention, cite and describe a brand, and that recommend content changes based on captured answers.'),
  ('ad_tech', 'Advertising Technology', 'software_sales_marketing', 'Sales and marketing software', 'Software for buying, serving, targeting and measuring paid digital ads, including demand-side platforms, ad servers, publisher monetisation and campaign management.'),
  ('customer_data_platforms', 'Customer Data Platforms', 'software_sales_marketing', 'Sales and marketing software', 'Systems that unify customer event and profile data from many sources into one identity and send audiences to other tools; data plumbing for marketers rather than a campaign tool.'),
  ('creator_affiliate_programs', 'Creator and Affiliate Programs', 'software_sales_marketing', 'Sales and marketing software', 'Software and networks for recruiting and paying influencers, affiliates and referral partners, tracking the sales or conversions that each outside partner produces.'),
  ('project_management', 'Project Management', 'software_operations', 'Operations and collaboration software', 'Tools for planning work with tasks, boards, timelines and assignments across a team; tracks who does what by when, while `knowledge_wikis` stores written information.'),
  ('team_communication', 'Team Communication', 'software_operations', 'Operations and collaboration software', 'Workplace chat, video meeting and internal calling products that let colleagues talk in channels or live calls.'),
  ('knowledge_wikis', 'Knowledge Bases and Wikis', 'software_operations', 'Operations and collaboration software', 'Workspaces for writing, organising and searching a team''s notes, documents and internal knowledge; the content is pages of text, not assigned tasks.'),
  ('esignature_contracts', 'E-Signature and Contracts', 'software_operations', 'Operations and collaboration software', 'Software to send documents for legally binding electronic signature and to draft, approve, store and renew business contracts.'),
  ('appointment_scheduling_software', 'Appointment Scheduling Software', 'software_operations', 'Operations and collaboration software', 'Booking links and calendars that let customers or colleagues pick an open time slot, used across any profession and not tied to one industry.'),
  ('customer_support_software', 'Customer Support Software', 'software_operations', 'Operations and collaboration software', 'Help desk, shared inbox, ticketing and live chat tools that service teams use to answer customer questions, including AI support agents.'),
  ('survey_form_tools', 'Survey and Form Tools', 'software_operations', 'Operations and collaboration software', 'Products for building online forms, questionnaires, quizzes and polls and for collecting and analysing the responses.'),
  ('workflow_automation', 'Workflow Automation', 'software_operations', 'Operations and collaboration software', 'Services that connect business apps and run multi-step automations between them through triggers and actions, without building a new application.'),
  ('no_code_builders', 'No-Code App Builders', 'software_operations', 'Operations and collaboration software', 'Platforms for building custom internal tools or web and mobile applications visually with little programming; the output is an app, while `website_builders` produces a marketing site.'),
  ('field_service_software', 'Field Service Software', 'software_operations', 'Operations and collaboration software', 'Dispatching, job scheduling, quoting and invoicing software for businesses that send technicians to customer sites, such as trades and home-service crews.'),
  ('website_builders', 'Website Builders', 'software_operations', 'Operations and collaboration software', 'Drag-and-drop and hosted content tools for creating and publishing websites, blogs and landing pages, including content management systems.'),
  ('accounting_software', 'Accounting Software', 'software_finance_people', 'Finance and people software', 'Bookkeeping, general ledger, invoicing and tax-filing applications used by small businesses and their accountants; narrower than the company-wide suites in `erp_software`.'),
  ('spend_management', 'Spend Management', 'software_finance_people', 'Finance and people software', 'Corporate cards, expense reports, purchasing approvals and vendor bill payment software that controls what employees and departments spend.'),
  ('subscription_billing', 'Subscription Billing', 'software_finance_people', 'Finance and people software', 'Software that manages recurring plans, usage-based charges, dunning and revenue recognition for subscription businesses, sitting above a payment gateway such as those in `payment_processing`.'),
  ('payroll_software', 'Payroll Software', 'software_finance_people', 'Finance and people software', 'Services that calculate and pay employee wages, withhold payroll taxes and file employment returns, including global employer-of-record payroll.'),
  ('hr_platforms', 'HR Platforms', 'software_finance_people', 'Finance and people software', 'Employee record systems covering onboarding, time off, benefits, performance reviews and engagement surveys for people already employed; hiring workflows belong in `applicant_tracking`.'),
  ('applicant_tracking', 'Applicant Tracking', 'software_finance_people', 'Finance and people software', 'Hiring software where recruiters post roles, screen candidates and move applicants through interview stages inside the employer''s own process.'),
  ('learning_management', 'Learning Management Systems', 'software_finance_people', 'Finance and people software', 'Software organisations use to deliver, assign and track employee or student training; sold to the institution, while `online_course_marketplaces` sells courses to learners.'),
  ('erp_software', 'ERP Software', 'software_finance_people', 'Finance and people software', 'Integrated enterprise suites running finance, inventory, supply chain and manufacturing together for mid-sized and large companies.'),
  ('cloud_infrastructure', 'Cloud Infrastructure', 'software_infrastructure_data_ai', 'Infrastructure, data and AI software', 'On-demand compute, storage, networking and application deployment platforms for engineering teams running production software at scale.'),
  ('web_hosting_domains', 'Web Hosting and Domains', 'software_infrastructure_data_ai', 'Infrastructure, data and AI software', 'Domain registration and shared, managed or WordPress hosting plans bought by site owners and small businesses rather than by engineering teams.'),
  ('code_hosting_devops', 'Code Hosting and DevOps', 'software_infrastructure_data_ai', 'Infrastructure, data and AI software', 'Developer tools for source control, code review, continuous integration, API design and testing, and shipping software releases.'),
  ('observability', 'Observability', 'software_infrastructure_data_ai', 'Infrastructure, data and AI software', 'Monitoring, logging, tracing and incident alerting products that show engineers how production systems are behaving.'),
  ('data_platforms', 'Data Platforms', 'software_infrastructure_data_ai', 'Infrastructure, data and AI software', 'Databases, data warehouses, data pipelines and vector stores that store and move an organisation''s data; infrastructure for data teams, while `business_intelligence` presents the results.'),
  ('business_intelligence', 'Business Intelligence', 'software_infrastructure_data_ai', 'Infrastructure, data and AI software', 'Dashboards, reporting and data visualisation tools that let business users explore company metrics drawn from many data sources.'),
  ('product_analytics', 'Product Analytics', 'software_infrastructure_data_ai', 'Infrastructure, data and AI software', 'Tools that record how users behave inside a website or app, with funnels, retention, session replay, feature flags and experiments.'),
  ('network_endpoint_security', 'Network and Endpoint Security', 'software_infrastructure_data_ai', 'Infrastructure, data and AI software', 'Enterprise cybersecurity products that detect and block attacks on devices, networks, email and cloud workloads, operated by security teams.'),
  ('identity_access_management', 'Identity and Access Management', 'software_infrastructure_data_ai', 'Infrastructure, data and AI software', 'Workforce or customer single sign-on, multi-factor login and permission systems that control who can reach which business applications.'),
  ('security_compliance_automation', 'Security Compliance Automation', 'software_infrastructure_data_ai', 'Infrastructure, data and AI software', 'Software that gathers evidence and tracks controls for audits and certifications such as SOC 2, ISO 27001 and HIPAA; proves security posture rather than blocking attacks.'),
  ('consumer_privacy_security', 'Consumer Privacy and Security', 'software_infrastructure_data_ai', 'Infrastructure, data and AI software', 'VPNs, antivirus, password managers and identity-theft protection sold to individuals and households for personal devices and accounts.'),
  ('ai_model_providers', 'AI Model Providers', 'software_infrastructure_data_ai', 'Infrastructure, data and AI software', 'Companies offering large language models, general-purpose AI assistants or model APIs that other products and people build on or chat with directly.'),
  ('ai_content_tools', 'AI Content Tools', 'software_infrastructure_data_ai', 'Infrastructure, data and AI software', 'Applications that generate or edit marketing copy, images, video, voice or presentations with AI for a specific creative task, built for content creators.'),
